class Solution {
    std::pair<int, int> dfs(TreeNode* node) {
        if (!node) return {0, 0};
        if (node->val == 0) return {0, 1};
        if (node->val == 1) return {1, 0};
        auto [lf, lt] = dfs(node->left);
        auto [rf, rt] = dfs(node->right);
        if (node->val == 2) { // OR
            return {lf + rf, std::min({lt + rt, lt + rf, lf + rt})};
        } else if (node->val == 3) { // AND
            return {std::min({lf + rf, lf + rt, lt + rf}), lt + rt};
        } else if (node->val == 4) { // XOR
            return {std::min(lf + rf, lt + rt), std::min(lf + rt, lt + rf)};
        } else if (node->val == 5) { // NOT
            auto child = node->left ? std::make_pair(lf, lt) : std::make_pair(rf, rt);
            return {child.second, child.first};
        }
        return {1000000, 1000000};
    }
public:
    int minimumFlips(TreeNode* root, bool result) {
        auto [cf, ct] = dfs(root);
        return result ? ct : cf;
    }
};

class Solution {
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        if (node.val == 0) return new int[]{0, 1};
        if (node.val == 1) return new int[]{1, 0};
        int[] left = dfs(node.left);
        int[] right = dfs(node.right);
        int lf = left[0], lt = left[1], rf = right[0], rt = right[1];
        if (node.val == 2) { // OR
            return new int[]{lf + rf, Math.min(lt + rt, Math.min(lt + rf, lf + rt))};
        } else if (node.val == 3) { // AND
            return new int[]{Math.min(lf + rf, Math.min(lf + rt, lt + rf)), lt + rt};
        } else if (node.val == 4) { // XOR
            return new int[]{Math.min(lf + rf, lt + rt), Math.min(lf + rt, lt + rf)};
        } else if (node.val == 5) { // NOT
            int[] child = node.left != null ? left : right;
            return new int[]{child[1], child[0]};
        }
        return new int[]{1000000, 1000000};
    }
    public int minimumFlips(TreeNode root, boolean result) {
        int[] res = dfs(root);
        return result ? res[1] : res[0];
    }
}

var minimumFlips = function(root, result) {
    const dfs = (node) => {
        if (!node) return [0, 0];
        if (node.val === 0) return [0, 1];
        if (node.val === 1) return [1, 0];
        const [lf, lt] = dfs(node.left);
        const [rf, rt] = dfs(node.right);
        if (node.val === 2) {
            return [lf + rf, Math.min(lt + rt, lt + rf, lf + rt)];
        } else if (node.val === 3) {
            return [Math.min(lf + rf, lf + rt, lt + rf), lt + rt];
        } else if (node.val === 4) {
            return [Math.min(lf + rf, lt + rt), Math.min(lf + rt, lt + rf)];
        } else if (node.val === 5) {
            const [cf, ct] = node.left ? [lf, lt] : [rf, rt];
            return [ct, cf];
        }
        return [1000000, 1000000];
    };
    const [cf, ct] = dfs(root);
    return result ? ct : cf;
};
